/**
 * Closed-Loop Scanner
 * Post-deployment verification with REAL governance score deltas and rollback recommendations.
 * Now integrates with the actual Gravito governance infrastructure via GovernanceIntegration.
 * Security hardened per Claude Sonnet 4.6 review.
 */
import { getWebsiteContentDeployer, type DeploymentRecord } from './website-content-deployer';
import { getGovernanceIntegration, type GovernanceSnapshot, type GovernanceCheckResult } from './governance-integration';
import { governanceLog } from '../_core/logger';

export type ScanStatus = 'pending' | 'in_progress' | 'completed' | 'failed';

export interface HealthDelta {
  governanceScoreBefore: number;
  governanceScoreAfter: number;
  governanceScoreDelta: number;
  improved: boolean;
  degraded: boolean;
  summary: string;
  checks: ScanCheck[];
  /** Full governance snapshot at scan time */
  snapshot?: GovernanceSnapshot;
}

export interface ScanCheck {
  name: string;
  passed: boolean;
  score: number;
  details?: string;
  source?: string;
}

export interface ScanResult {
  id: string;
  deploymentId: string;
  status: ScanStatus;
  startedAt: number;
  completedAt?: number;
  delta?: HealthDelta;
  recommendRollback: boolean;
  rollbackReason?: string;
  error?: string;
}

export interface ScannerConfig {
  enabled: boolean;
  autoScanAfterDeploy: boolean;
  degradationThreshold: number;
  autoRollbackOnDegradation: boolean;
  maxScanHistory: number;
  scanTimeoutMs: number;
  checks: string[];
  /** Use real governance integration instead of mock checks */
  useRealGovernance: boolean;
}

const DEFAULT_SCANNER_CONFIG: ScannerConfig = {
  enabled: true,
  autoScanAfterDeploy: true,
  degradationThreshold: -0.05,
  autoRollbackOnDegradation: false,
  maxScanHistory: 500,
  scanTimeoutMs: 30000,
  checks: ['governance_score', 'content_integrity', 'performance', 'accessibility'],
  useRealGovernance: true,
};

export class ClosedLoopScanner {
  private config: ScannerConfig;
  private scanHistory: ScanResult[] = [];
  private baselineMetrics: Record<string, number> = {};
  /** Cached pre-deployment snapshot for delta comparison */
  private preDeploySnapshot: GovernanceSnapshot | null = null;

  constructor(config?: Partial<ScannerConfig>) {
    this.config = { ...DEFAULT_SCANNER_CONFIG, ...config };
  }

  /**
   * Capture a pre-deployment governance snapshot.
   * Call this BEFORE deploying to enable accurate delta comparison.
   */
  async capturePreDeploySnapshot(): Promise<GovernanceSnapshot> {
    const gi = getGovernanceIntegration();
    gi.clearCache(); // Force fresh data
    const timeoutMs = this.config.scanTimeoutMs ?? 30000;
    const timeoutPromise = new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error('Pre-deploy snapshot timed out')), timeoutMs)
    );
    this.preDeploySnapshot = await Promise.race([
      gi.takeSnapshot(),
      timeoutPromise,
    ]);
    return this.preDeploySnapshot;
  }

  async scanDeployment(deploymentId: string): Promise<ScanResult> {
    const id = `scan_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;
    const result: ScanResult = {
      id, deploymentId, status: 'pending', startedAt: Date.now(), recommendRollback: false,
    };
    try {
      if (!this.config.enabled) throw new Error('Scanner disabled');
      result.status = 'in_progress';

      let checks: ScanCheck[];
      let avgScore: number;
      let baselineScore: number;
      let snapshot: GovernanceSnapshot | undefined;

      if (this.config.useRealGovernance) {
        // Use real governance integration
        const gi = getGovernanceIntegration();
        gi.clearCache(); // Force fresh data post-deployment
        snapshot = await gi.takeSnapshot();

        // Convert governance checks to scan checks
        checks = snapshot.checks.map(gc => ({
          name: gc.name,
          passed: gc.passed,
          score: gc.score,
          details: gc.details,
          source: gc.source,
        }));

        avgScore = snapshot.overallScore;
        baselineScore = this.preDeploySnapshot?.overallScore ?? this.baselineMetrics['governance_score'] ?? 0.85;
      } else {
        // Fallback to mock checks (for testing or when governance is unavailable)
        checks = [];
        for (const checkName of this.config.checks) {
          const check = await this.runMockCheck(checkName, deploymentId);
          checks.push(check);
        }
        avgScore = checks.length > 0 ? checks.reduce((s, c) => s + c.score, 0) / checks.length : 0;
        baselineScore = this.baselineMetrics['governance_score'] ?? 0.85;
      }

      const delta = avgScore - baselineScore;

      result.delta = {
        governanceScoreBefore: baselineScore,
        governanceScoreAfter: avgScore,
        governanceScoreDelta: delta,
        improved: delta > 0.01,
        degraded: delta < this.config.degradationThreshold,
        summary: delta > 0.01
          ? `Improvement detected: governance score increased by ${(delta * 100).toFixed(1)}%`
          : delta < this.config.degradationThreshold
            ? `Degradation detected: governance score decreased by ${(Math.abs(delta) * 100).toFixed(1)}%`
            : 'No significant governance change',
        checks,
        snapshot,
      };

      if (result.delta.degraded) {
        result.recommendRollback = true;
        result.rollbackReason = `Governance score degraded by ${(Math.abs(delta) * 100).toFixed(1)}% (from ${(baselineScore * 100).toFixed(1)}% to ${(avgScore * 100).toFixed(1)}%)`;
        if (this.config.autoRollbackOnDegradation) {
          try {
            const deployer = getWebsiteContentDeployer();
            await deployer.rollback(deploymentId, result.rollbackReason);
          } catch (err) {
            governanceLog.error(`[ClosedLoopScanner] Auto-rollback failed for deployment ${deploymentId}`, err);
          }
        }
      }

      // Update baseline with current snapshot for next comparison
      if (snapshot && !result.delta.degraded) {
        this.baselineMetrics['governance_score'] = avgScore;
      }

      // Clear pre-deploy snapshot after scan
      this.preDeploySnapshot = null;

      result.status = 'completed';
      result.completedAt = Date.now();
    } catch (err: unknown) {
      result.status = 'failed';
      result.error = err instanceof Error ? err.message : String(err);
      result.completedAt = Date.now();
    }
    this.scanHistory.push(result);
    if (this.scanHistory.length > this.config.maxScanHistory) {
      this.scanHistory.splice(0, this.scanHistory.length - this.config.maxScanHistory);
    }
    return result;
  }

  /**
   * Mock check fallback — used when real governance is unavailable or disabled.
   */
  private async runMockCheck(name: string, _deploymentId: string): Promise<ScanCheck> {
    const baseScore = this.baselineMetrics[name] ?? 0.85;
    const variation = (Math.random() - 0.5) * 0.1;
    const score = Math.max(0, Math.min(1, baseScore + variation));
    return { name, passed: score >= 0.7, score, details: `Mock score: ${(score * 100).toFixed(1)}%`, source: 'mock' };
  }

  setBaseline(metrics: Record<string, number>) { this.baselineMetrics = { ...metrics }; }
  getBaseline() { return { ...this.baselineMetrics }; }
  getScanHistory(limit = 50) { return this.scanHistory.slice(-limit); }
  getScanResult(id: string) { return this.scanHistory.find(s => s.id === id); }
  getStats() {
    return {
      totalScans: this.scanHistory.length,
      completedScans: this.scanHistory.filter(s => s.status === 'completed').length,
      failedScans: this.scanHistory.filter(s => s.status === 'failed').length,
      rollbacksTriggered: this.scanHistory.filter(s => s.recommendRollback).length,
      usingRealGovernance: this.config.useRealGovernance,
    };
  }
  updateConfig(u: Partial<ScannerConfig>) { this.config = { ...this.config, ...u }; }
  getConfig(): ScannerConfig { return { ...this.config }; }
}

let inst: ClosedLoopScanner | null = null;
export function getClosedLoopScanner() { if (!inst) inst = new ClosedLoopScanner(); return inst; }
export function resetClosedLoopScanner() { inst = null; }

