1	/**
2	 * Multi-Channel Notification Dispatcher
3	 * 
4	 * Extends the alerting pipeline with multiple notification channels:
5	 * - In-App (Manus notification service — always available)
6	 * - Slack (webhook — already implemented)
7	 * - Email (SMTP or API-based — configurable)
8	 * - SMS (Twilio-compatible API — configurable)
9	 * - Generic Webhook (custom HTTP endpoint — configurable)
10	 * 
11	 * Each channel has:
12	 * - Independent enable/disable toggle
13	 * - Severity filtering (e.g., only critical alerts via SMS)
14	 * - Rate limiting per channel
15	 * - Delivery status tracking
16	 * - Retry with exponential backoff
17	 * 
18	 * Architecture:
19	 * - Channels are registered at startup
20	 * - Alerts are dispatched to all enabled channels matching severity
21	 * - Delivery results are aggregated and returned
22	 * - Failed deliveries are logged and retried (configurable)
23	 */
24	
25	import { generalLog } from '../_core/logger';
26	
27	// ============================================================================
28	// TYPES
29	// ============================================================================
30	
31	export type ChannelType = 'in_app' | 'slack' | 'email' | 'sms' | 'webhook';
32	export type AlertSeverity = 'info' | 'warning' | 'critical';
33	
34	export interface ChannelConfig {
35	  id: string;
36	  type: ChannelType;
37	  name: string;
38	  enabled: boolean;
39	  /** Minimum severity to trigger this channel */
40	  minSeverity: AlertSeverity;
41	  /** Rate limit: max alerts per hour for this channel */
42	  maxPerHour: number;
43	  /** Retry count on failure */
44	  retryCount: number;
45	  /** Retry delay base in ms (exponential backoff) */
46	  retryDelayMs: number;
47	  /** Channel-specific configuration */
48	  settings: Record<string, string>;
49	}
50	
51	export interface NotificationPayload {
52	  title: string;
53	  content: string;
54	  severity: AlertSeverity;
55	  source: string;
56	  timestamp: number;
57	  metadata?: Record<string, unknown>;
58	}
59	
60	export interface DeliveryResult {
61	  channelId: string;
62	  channelType: ChannelType;
63	  channelName: string;
64	  success: boolean;
65	  attempts: number;
66	  latencyMs: number;
67	  error?: string;
68	  timestamp: number;
69	}
70	
71	export interface ChannelStats {
72	  channelId: string;
73	  channelType: ChannelType;
74	  channelName: string;
75	  enabled: boolean;
76	  totalSent: number;
77	  totalFailed: number;
78	  totalRetried: number;
79	  sentThisHour: number;
80	  lastDelivery: number | null;
81	  lastError: string | null;
82	  avgLatencyMs: number;
83	}
84	
85	// ============================================================================
86	// SEVERITY HELPERS
87	// ============================================================================
88	
89	const SEVERITY_LEVELS: Record<AlertSeverity, number> = {
90	  info: 0,
91	  warning: 1,
92	  critical: 2,
93	};
94	
95	function meetsMinSeverity(severity: AlertSeverity, minSeverity: AlertSeverity): boolean {
96	  return SEVERITY_LEVELS[severity] >= SEVERITY_LEVELS[minSeverity];
97	}
98	
99	// ============================================================================
100	// CHANNEL SENDERS
101	// ============================================================================
102	
103	/**
104	 * Send via Slack webhook with Block Kit formatting.
105	 */
106	async function sendSlack(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
107	  const webhookUrl = config.settings.webhookUrl;
108	  if (!webhookUrl) throw new Error('Slack webhook URL not configured');
109	
110	  const colorMap: Record<string, string> = {
111	    critical: '#dc2626',
112	    warning: '#f59e0b',
113	    info: '#3b82f6',
114	  };
115	
116	  const body = {
117	    blocks: [
118	      {
119	        type: 'header',
120	        text: { type: 'plain_text', text: payload.title.slice(0, 150), emoji: true },
121	      },
122	      {
123	        type: 'section',
124	        text: { type: 'mrkdwn', text: payload.content.slice(0, 3000) },
125	      },
126	      {
127	        type: 'context',
128	        elements: [
129	          { type: 'mrkdwn', text: `*Severity:* ${payload.severity.toUpperCase()} | *Source:* ${payload.source} | *Time:* ${new Date(payload.timestamp).toISOString()}` },
130	        ],
131	      },
132	      { type: 'divider' },
133	    ],
134	    attachments: [{ color: colorMap[payload.severity] ?? '#6b7280', fallback: payload.title }],
135	  };
136	
137	  const resp = await fetch(webhookUrl, {
138	    method: 'POST',
139	    headers: { 'Content-Type': 'application/json' },
140	    body: JSON.stringify(body),
141	    signal: AbortSignal.timeout(10_000),
142	  });
143	
144	  if (!resp.ok) {
145	    throw new Error(`Slack returned HTTP ${resp.status}: ${await resp.text().catch(() => '')}`);
146	  }
147	}
148	
149	/**
150	 * Send via email using a generic SMTP/API endpoint.
151	 * Supports: SendGrid, Mailgun, Postmark, or any REST-based email API.
152	 */
153	async function sendEmail(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
154	  const apiUrl = config.settings.apiUrl;
155	  const apiKey = config.settings.apiKey;
156	  const fromEmail = config.settings.fromEmail || 'alerts@gravito.ai';
157	  const toEmails = config.settings.toEmails; // comma-separated
158	
159	  if (!apiUrl || !apiKey || !toEmails) {
160	    throw new Error('Email channel not fully configured (requires apiUrl, apiKey, toEmails)');
161	  }
162	
163	  const recipients = toEmails.split(',').map(e => e.trim()).filter(Boolean);
164	  if (recipients.length === 0) throw new Error('No email recipients configured');
165	
166	  // Format email body as HTML
167	  const severityColors: Record<string, string> = {
168	    critical: '#dc2626',
169	    warning: '#f59e0b',
170	    info: '#3b82f6',
171	  };
172	
173	  const htmlBody = `
174	    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto;">
175	      <div style="background: ${severityColors[payload.severity] ?? '#6b7280'}; color: white; padding: 16px 24px; border-radius: 8px 8px 0 0;">
176	        <h2 style="margin: 0; font-size: 18px;">${escapeHtml(payload.title)}</h2>
177	      </div>
178	      <div style="background: #1c1917; color: #d6d3d1; padding: 24px; border: 1px solid #292524;">
179	        <div style="white-space: pre-wrap; line-height: 1.6;">${escapeHtml(payload.content)}</div>
180	        <hr style="border: none; border-top: 1px solid #44403c; margin: 16px 0;" />
181	        <div style="font-size: 12px; color: #78716c;">
182	          <strong>Severity:</strong> ${payload.severity.toUpperCase()} |
183	          <strong>Source:</strong> ${escapeHtml(payload.source)} |
184	          <strong>Time:</strong> ${new Date(payload.timestamp).toISOString()}
185	        </div>
186	      </div>
187	      <div style="background: #0c0a09; color: #57534e; padding: 12px 24px; border-radius: 0 0 8px 8px; font-size: 11px;">
188	        Gravito AI — Alert Pipeline
189	      </div>
190	    </div>
191	  `;
192	
193	  // Generic REST email API (SendGrid-compatible format)
194	  const emailPayload = {
195	    personalizations: recipients.map(to => ({ to: [{ email: to }] })),
196	    from: { email: fromEmail, name: 'Gravito Alerts' },
197	    subject: `[${payload.severity.toUpperCase()}] ${payload.title}`,
198	    content: [
199	      { type: 'text/plain', value: `${payload.title}\n\n${payload.content}\n\nSeverity: ${payload.severity}\nSource: ${payload.source}\nTime: ${new Date(payload.timestamp).toISOString()}` },
200	      { type: 'text/html', value: htmlBody },
201	    ],
202	  };
203	
204	  const resp = await fetch(apiUrl, {
205	    method: 'POST',
206	    headers: {
207	      'Content-Type': 'application/json',
208	      'Authorization': `Bearer ${apiKey}`,
209	    },
210	    body: JSON.stringify(emailPayload),
211	    signal: AbortSignal.timeout(15_000),
212	  });
213	
214	  if (!resp.ok) {
215	    throw new Error(`Email API returned HTTP ${resp.status}: ${await resp.text().catch(() => '')}`);
216	  }
217	}
218	
219	/**
220	 * Send via SMS using a Twilio-compatible API.
221	 */
222	async function sendSMS(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
223	  const accountSid = config.settings.accountSid;
224	  const authToken = config.settings.authToken;
225	  const fromNumber = config.settings.fromNumber;
226	  const toNumbers = config.settings.toNumbers; // comma-separated
227	
228	  if (!accountSid || !authToken || !fromNumber || !toNumbers) {
229	    throw new Error('SMS channel not fully configured (requires accountSid, authToken, fromNumber, toNumbers)');
230	  }
231	
232	  const recipients = toNumbers.split(',').map(n => n.trim()).filter(Boolean);
233	  if (recipients.length === 0) throw new Error('No SMS recipients configured');
234	
235	  // Truncate for SMS (160 char limit per segment)
236	  const smsBody = `[Gravito ${payload.severity.toUpperCase()}] ${payload.title}\n${payload.content}`.slice(0, 1500);
237	
238	  const apiUrl = config.settings.apiUrl || `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
239	  const authHeader = 'Basic ' + Buffer.from(`${accountSid}:${authToken}`).toString('base64');
240	
241	  // Send to each recipient
242	  const errors: string[] = [];
243	  for (const to of recipients) {
244	    try {
245	      const resp = await fetch(apiUrl, {
246	        method: 'POST',
247	        headers: {
248	          'Content-Type': 'application/x-www-form-urlencoded',
249	          'Authorization': authHeader,
250	        },
251	        body: new URLSearchParams({ To: to, From: fromNumber, Body: smsBody }).toString(),
252	        signal: AbortSignal.timeout(15_000),
253	      });
254	
255	      if (!resp.ok) {
256	        errors.push(`${to}: HTTP ${resp.status}`);
257	      }
258	    } catch (err: any) {
259	      errors.push(`${to}: ${err?.message ?? 'unknown'}`);
260	    }
261	  }
262	
263	  if (errors.length > 0) {
264	    throw new Error(`SMS delivery failed for: ${errors.join('; ')}`);
265	  }
266	}
267	
268	/**
269	 * Send via generic webhook (HTTP POST with JSON body).
270	 */
271	async function sendWebhook(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
272	  const url = config.settings.url;
273	  if (!url) throw new Error('Webhook URL not configured');
274	
275	  const headers: Record<string, string> = {
276	    'Content-Type': 'application/json',
277	  };
278	
279	  // Optional auth header
280	  if (config.settings.authHeader) {
281	    headers['Authorization'] = config.settings.authHeader;
282	  }
283	
284	  // Optional custom headers (JSON-encoded)
285	  if (config.settings.customHeaders) {
286	    try {
287	      const custom = JSON.parse(config.settings.customHeaders);
288	      Object.assign(headers, custom);
289	    } catch { /* ignore malformed headers */ }
290	  }
291	
292	  const body = {
293	    event: 'gravito.alert',
294	    severity: payload.severity,
295	    title: payload.title,
296	    content: payload.content,
297	    source: payload.source,
298	    timestamp: payload.timestamp,
299	    metadata: payload.metadata ?? {},
300	  };
301	
302	  const resp = await fetch(url, {
303	    method: 'POST',
304	    headers,
305	    body: JSON.stringify(body),
306	    signal: AbortSignal.timeout(10_000),
307	  });
308	
309	  if (!resp.ok) {
310	    throw new Error(`Webhook returned HTTP ${resp.status}: ${await resp.text().catch(() => '')}`);
311	  }
312	}
313	
314	/**
315	 * Send via in-app notification (Manus notification service).
316	 */
317	async function sendInApp(_config: ChannelConfig, payload: NotificationPayload): Promise<void> {
318	  const { notifyOwnerDirect } = await import('../_core/notification');
319	  const delivered = await notifyOwnerDirect({
320	    title: payload.title,
321	    content: payload.content,
322	  });
323	  if (!delivered) {
324	    throw new Error('In-app notification delivery failed');
325	  }
326	}
327	
328	// ============================================================================
329	// SENDER REGISTRY
330	// ============================================================================
331	
332	const SENDERS: Record<ChannelType, (config: ChannelConfig, payload: NotificationPayload) => Promise<void>> = {
333	  in_app: sendInApp,
334	  slack: sendSlack,
335	  email: sendEmail,
336	  sms: sendSMS,
337	  webhook: sendWebhook,
338	};
339	
340	// ============================================================================
341	// HTML ESCAPE HELPER
342	// ============================================================================
343	
344	function escapeHtml(str: string): string {
345	  return str
346	    .replace(/&/g, '&amp;')
347	    .replace(/</g, '&lt;')
348	    .replace(/>/g, '&gt;')
349	    .replace(/"/g, '&quot;')
350	    .replace(/'/g, '&#039;');
351	}
352	
353	// ============================================================================
354	// MULTI-CHANNEL NOTIFIER
355	// ============================================================================
356	
357	export class MultiChannelNotifier {
358	  private channels: Map<string, ChannelConfig> = new Map();
359	  private stats: Map<string, {
360	    totalSent: number;
361	    totalFailed: number;
362	    totalRetried: number;
363	    sentThisHour: number;
364	    lastDelivery: number | null;
365	    lastError: string | null;
366	    latencies: number[];
367	  }> = new Map();
368	  private deliveryLog: DeliveryResult[] = [];
369	  private hourResetTimer: ReturnType<typeof setInterval> | null = null;
370	
371	  constructor() {
372	    // Register default in-app channel
373	    this.registerChannel({
374	      id: 'in-app-default',
375	      type: 'in_app',
376	      name: 'In-App Notifications',
377	      enabled: true,
378	      minSeverity: 'info',
379	      maxPerHour: 50,
380	      retryCount: 1,
381	      retryDelayMs: 2000,
382	      settings: {},
383	    });
384	
385	    // Auto-configure Slack from environment
386	    const slackUrl = process.env.SLACK_WEBHOOK_URL;
387	    if (slackUrl) {
388	      this.registerChannel({
389	        id: 'slack-default',
390	        type: 'slack',
391	        name: 'Slack Alerts',
392	        enabled: true,
393	        minSeverity: 'warning',
394	        maxPerHour: 30,
395	        retryCount: 2,
396	        retryDelayMs: 2000,
397	        settings: { webhookUrl: slackUrl },
398	      });
399	    }
400	
401	    // Start hourly rate limit reset
402	    this.hourResetTimer = setInterval(() => {
403	      for (const [, stat] of this.stats) {
404	        stat.sentThisHour = 0;
405	      }
406	    }, 60 * 60 * 1000);
407	  }
408	
409	  // ─── Channel Management ──────────────────────────────────────────────
410	
411	  registerChannel(config: ChannelConfig): void {
412	    this.channels.set(config.id, { ...config });
413	    if (!this.stats.has(config.id)) {
414	      this.stats.set(config.id, {
415	        totalSent: 0,
416	        totalFailed: 0,
417	        totalRetried: 0,
418	        sentThisHour: 0,
419	        lastDelivery: null,
420	        lastError: null,
421	        latencies: [],
422	      });
423	    }
424	    generalLog.info({}, `[MultiChannel] Channel registered: ${config.name} (${config.type})`);
425	  }
426	
427	  removeChannel(channelId: string): boolean {
428	    const removed = this.channels.delete(channelId);
429	    if (removed) {
430	      generalLog.info({}, `[MultiChannel] Channel removed: ${channelId}`);
431	    }
432	    return removed;
433	  }
434	
435	  updateChannel(channelId: string, updates: Partial<Omit<ChannelConfig, 'id' | 'type'>>): ChannelConfig | null {
436	    const channel = this.channels.get(channelId);
437	    if (!channel) return null;
438	
439	    const updated = { ...channel, ...updates };
440	    if (updates.settings) {
441	      updated.settings = { ...channel.settings, ...updates.settings };
442	    }
443	    this.channels.set(channelId, updated);
444	    return { ...updated };
445	  }
446	
447	  getChannel(channelId: string): ChannelConfig | null {
448	    const ch = this.channels.get(channelId);
449	    return ch ? { ...ch } : null;
450	  }
451	
452	  getChannels(): ChannelConfig[] {
453	    return Array.from(this.channels.values()).map(ch => ({
454	      ...ch,
455	      // Mask sensitive settings
456	      settings: Object.fromEntries(
457	        Object.entries(ch.settings).map(([k, v]) => {
458	          if (k.toLowerCase().includes('key') || k.toLowerCase().includes('token') || k.toLowerCase().includes('secret') || k.toLowerCase().includes('password')) {
459	            return [k, v ? `${v.slice(0, 6)}...` : ''];
460	          }
461	          return [k, v];
462	        })
463	      ),
464	    }));
465	  }
466	
467	  // ─── Dispatch ────────────────────────────────────────────────────────
468	
469	  /**
470	   * Dispatch a notification to all enabled channels matching severity.
471	   * Returns delivery results for each channel.
472	   */
473	  async dispatch(payload: NotificationPayload): Promise<DeliveryResult[]> {
474	    const results: DeliveryResult[] = [];
475	
476	    for (const [channelId, config] of this.channels) {
477	      if (!config.enabled) continue;
478	      if (!meetsMinSeverity(payload.severity, config.minSeverity)) continue;
479	
480	      const stat = this.stats.get(channelId)!;
481	      if (stat.sentThisHour >= config.maxPerHour) {
482	        generalLog.warn({}, `[MultiChannel] Rate limit reached for ${config.name}, skipping`);
483	        results.push({
484	          channelId,
485	          channelType: config.type,
486	          channelName: config.name,
487	          success: false,
488	          attempts: 0,
489	          latencyMs: 0,
490	          error: 'Rate limit exceeded',
491	          timestamp: Date.now(),
492	        });
493	        continue;
494	      }
495	
496	      const result = await this.sendWithRetry(channelId, config, payload);
497	      results.push(result);
498	    }
499	
500	    return results;
501	  }
502	
503	  private async sendWithRetry(
504	    channelId: string,
505	    config: ChannelConfig,
506	    payload: NotificationPayload
507	  ): Promise<DeliveryResult> {
508	    const sender = SENDERS[config.type];
509	    if (!sender) {
510	      return {
511	        channelId,
512	        channelType: config.type,
513	        channelName: config.name,
514	        success: false,
515	        attempts: 0,
516	        latencyMs: 0,
517	        error: `Unknown channel type: ${config.type}`,
518	        timestamp: Date.now(),
519	      };
520	    }
521	
522	    const stat = this.stats.get(channelId)!;
523	    let lastError: string | undefined;
524	    const startTime = Date.now();
525	
526	    for (let attempt = 0; attempt <= config.retryCount; attempt++) {
527	      try {
528	        if (attempt > 0) {
529	          const delay = config.retryDelayMs * Math.pow(2, attempt - 1);
530	          await new Promise(r => setTimeout(r, delay));
531	          stat.totalRetried++;
532	        }
533	
534	        await sender(config, payload);
535	
536	        // Success
537	        const latencyMs = Date.now() - startTime;
538	        stat.totalSent++;
539	        stat.sentThisHour++;
540	        stat.lastDelivery = Date.now();
541	        stat.latencies.push(latencyMs);
542	        if (stat.latencies.length > 100) stat.latencies.splice(0, stat.latencies.length - 100);
543	
544	        const result: DeliveryResult = {
545	          channelId,
546	          channelType: config.type,
547	          channelName: config.name,
548	          success: true,
549	          attempts: attempt + 1,
550	          latencyMs,
551	          timestamp: Date.now(),
552	        };
553	
554	        this.deliveryLog.push(result);
555	        this.trimDeliveryLog();
556	        return result;
557	      } catch (err: any) {
558	        lastError = err?.message ?? 'Unknown error';
559	        generalLog.warn({}, `[MultiChannel] ${config.name} attempt ${attempt + 1} failed: ${lastError}`);
560	      }
561	    }
562	
563	    // All attempts failed
564	    stat.totalFailed++;
565	    stat.lastError = lastError ?? 'Unknown error';
566	
567	    const result: DeliveryResult = {
568	      channelId,
569	      channelType: config.type,
570	      channelName: config.name,
571	      success: false,
572	      attempts: config.retryCount + 1,
573	      latencyMs: Date.now() - startTime,
574	      error: lastError,
575	      timestamp: Date.now(),
576	    };
577	
578	    this.deliveryLog.push(result);
579	    this.trimDeliveryLog();
580	    return result;
581	  }
582	
583	  // ─── Stats & History ─────────────────────────────────────────────────
584	
585	  getStats(): ChannelStats[] {
586	    return Array.from(this.channels.entries()).map(([channelId, config]) => {
587	      const stat = this.stats.get(channelId)!;
588	      const avgLatency = stat.latencies.length > 0
589	        ? stat.latencies.reduce((s, l) => s + l, 0) / stat.latencies.length
590	        : 0;
591	
592	      return {
593	        channelId,
594	        channelType: config.type,
595	        channelName: config.name,
596	        enabled: config.enabled,
597	        totalSent: stat.totalSent,
598	        totalFailed: stat.totalFailed,
599	        totalRetried: stat.totalRetried,
600	        sentThisHour: stat.sentThisHour,
601	        lastDelivery: stat.lastDelivery,
602	        lastError: stat.lastError,
603	        avgLatencyMs: Math.round(avgLatency),
604	      };
605	    });
606	  }
607	
608	  getDeliveryLog(limit = 50): DeliveryResult[] {
609	    return this.deliveryLog.slice(-limit);
610	  }
611	
612	  getSummary(): {
613	    totalChannels: number;
614	    enabledChannels: number;
615	    channelTypes: ChannelType[];
616	    totalDelivered: number;
617	    totalFailed: number;
618	    overallSuccessRate: number;
619	  } {
620	    const stats = this.getStats();
621	    const totalDelivered = stats.reduce((s, c) => s + c.totalSent, 0);
622	    const totalFailed = stats.reduce((s, c) => s + c.totalFailed, 0);
623	    const total = totalDelivered + totalFailed;
624	
625	    return {
626	      totalChannels: this.channels.size,
627	      enabledChannels: stats.filter(s => s.enabled).length,
628	      channelTypes: [...new Set(stats.map(s => s.channelType))],
629	      totalDelivered,
630	      totalFailed,
631	      overallSuccessRate: total > 0 ? totalDelivered / total : 1,
632	    };
633	  }
634	
635	  // ─── Test Channel ────────────────────────────────────────────────────
636	
637	  async testChannel(channelId: string): Promise<DeliveryResult> {
638	    const config = this.channels.get(channelId);
639	    if (!config) {
640	      return {
641	        channelId,
642	        channelType: 'webhook',
643	        channelName: 'Unknown',
644	        success: false,
645	        attempts: 0,
646	        latencyMs: 0,
647	        error: `Channel ${channelId} not found`,
648	        timestamp: Date.now(),
649	      };
650	    }
651	
652	    const testPayload: NotificationPayload = {
653	      title: `Test Alert — ${config.name}`,
654	      content: `This is a test notification from Gravito Alert Pipeline.\nChannel: ${config.name} (${config.type})\nTime: ${new Date().toISOString()}`,
655	      severity: 'info',
656	      source: 'multi-channel-test',
657	      timestamp: Date.now(),
658	    };
659	
660	    return this.sendWithRetry(channelId, config, testPayload);
661	  }
662	
663	  // ─── Cleanup ─────────────────────────────────────────────────────────
664	
665	  private trimDeliveryLog(): void {
666	    if (this.deliveryLog.length > 500) {
667	      this.deliveryLog.splice(0, this.deliveryLog.length - 500);
668	    }
669	  }
670	
671	  reset(): void {
672	    this.channels.clear();
673	    this.stats.clear();
674	    this.deliveryLog = [];
675	    if (this.hourResetTimer) {
676	      clearInterval(this.hourResetTimer);
677	      this.hourResetTimer = null;
678	    }
679	  }
680	
681	  destroy(): void {
682	    this.reset();
683	  }
684	}
685	
686	// ============================================================================
687	// SINGLETON
688	// ============================================================================
689	
690	let instance: MultiChannelNotifier | null = null;
691	
692	export function getMultiChannelNotifier(): MultiChannelNotifier {
693	  if (!instance) instance = new MultiChannelNotifier();
694	  return instance;
695	}
696	
697	export function resetMultiChannelNotifier(): void {
698	  if (instance) instance.destroy();
699	  instance = null;
700	}
