/**
 * Multi-Channel Notification Dispatcher
 * 
 * Extends the alerting pipeline with multiple notification channels:
 * - In-App (Manus notification service — always available)
 * - Slack (webhook — already implemented)
 * - Email (SMTP or API-based — configurable)
 * - SMS (Twilio-compatible API — configurable)
 * - Generic Webhook (custom HTTP endpoint — configurable)
 * 
 * Each channel has:
 * - Independent enable/disable toggle
 * - Severity filtering (e.g., only critical alerts via SMS)
 * - Rate limiting per channel
 * - Delivery status tracking
 * - Retry with exponential backoff
 * 
 * Architecture:
 * - Channels are registered at startup
 * - Alerts are dispatched to all enabled channels matching severity
 * - Delivery results are aggregated and returned
 * - Failed deliveries are logged and retried (configurable)
 */

import { generalLog } from '../_core/logger';

// ============================================================================
// TYPES
// ============================================================================

export type ChannelType = 'in_app' | 'slack' | 'email' | 'sms' | 'webhook';
export type AlertSeverity = 'info' | 'warning' | 'critical';

export interface ChannelConfig {
  id: string;
  type: ChannelType;
  name: string;
  enabled: boolean;
  /** Minimum severity to trigger this channel */
  minSeverity: AlertSeverity;
  /** Rate limit: max alerts per hour for this channel */
  maxPerHour: number;
  /** Retry count on failure */
  retryCount: number;
  /** Retry delay base in ms (exponential backoff) */
  retryDelayMs: number;
  /** Channel-specific configuration */
  settings: Record<string, string>;
}

export interface NotificationPayload {
  title: string;
  content: string;
  severity: AlertSeverity;
  source: string;
  timestamp: number;
  metadata?: Record<string, unknown>;
}

export interface DeliveryResult {
  channelId: string;
  channelType: ChannelType;
  channelName: string;
  success: boolean;
  attempts: number;
  latencyMs: number;
  error?: string;
  timestamp: number;
}

export interface ChannelStats {
  channelId: string;
  channelType: ChannelType;
  channelName: string;
  enabled: boolean;
  totalSent: number;
  totalFailed: number;
  totalRetried: number;
  sentThisHour: number;
  lastDelivery: number | null;
  lastError: string | null;
  avgLatencyMs: number;
}

// ============================================================================
// SEVERITY HELPERS
// ============================================================================

const SEVERITY_LEVELS: Record<AlertSeverity, number> = {
  info: 0,
  warning: 1,
  critical: 2,
};

function meetsMinSeverity(severity: AlertSeverity, minSeverity: AlertSeverity): boolean {
  return SEVERITY_LEVELS[severity] >= SEVERITY_LEVELS[minSeverity];
}

// ============================================================================
// CHANNEL SENDERS
// ============================================================================

/**
 * Send via Slack webhook with Block Kit formatting.
 */
async function sendSlack(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
  const webhookUrl = config.settings.webhookUrl;
  if (!webhookUrl) throw new Error('Slack webhook URL not configured');

  const colorMap: Record<string, string> = {
    critical: '#dc2626',
    warning: '#f59e0b',
    info: '#3b82f6',
  };

  const body = {
    blocks: [
      {
        type: 'header',
        text: { type: 'plain_text', text: payload.title.slice(0, 150), emoji: true },
      },
      {
        type: 'section',
        text: { type: 'mrkdwn', text: payload.content.slice(0, 3000) },
      },
      {
        type: 'context',
        elements: [
          { type: 'mrkdwn', text: `*Severity:* ${payload.severity.toUpperCase()} | *Source:* ${payload.source} | *Time:* ${new Date(payload.timestamp).toISOString()}` },
        ],
      },
      { type: 'divider' },
    ],
    attachments: [{ color: colorMap[payload.severity] ?? '#6b7280', fallback: payload.title }],
  };

  const resp = await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(10_000),
  });

  if (!resp.ok) {
    throw new Error(`Slack returned HTTP ${resp.status}: ${await resp.text().catch(() => '')}`);
  }
}

/**
 * Send via email using a generic SMTP/API endpoint.
 * Supports: SendGrid, Mailgun, Postmark, or any REST-based email API.
 */
async function sendEmail(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
  const apiUrl = config.settings.apiUrl;
  const apiKey = config.settings.apiKey;
  const fromEmail = config.settings.fromEmail || 'alerts@gravito.ai';
  const toEmails = config.settings.toEmails; // comma-separated

  if (!apiUrl || !apiKey || !toEmails) {
    throw new Error('Email channel not fully configured (requires apiUrl, apiKey, toEmails)');
  }

  const recipients = toEmails.split(',').map(e => e.trim()).filter(Boolean);
  if (recipients.length === 0) throw new Error('No email recipients configured');

  // Format email body as HTML
  const severityColors: Record<string, string> = {
    critical: '#dc2626',
    warning: '#f59e0b',
    info: '#3b82f6',
  };

  const htmlBody = `
    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto;">
      <div style="background: ${severityColors[payload.severity] ?? '#6b7280'}; color: white; padding: 16px 24px; border-radius: 8px 8px 0 0;">
        <h2 style="margin: 0; font-size: 18px;">${escapeHtml(payload.title)}</h2>
      </div>
      <div style="background: #1c1917; color: #d6d3d1; padding: 24px; border: 1px solid #292524;">
        <div style="white-space: pre-wrap; line-height: 1.6;">${escapeHtml(payload.content)}</div>
        <hr style="border: none; border-top: 1px solid #44403c; margin: 16px 0;" />
        <div style="font-size: 12px; color: #78716c;">
          <strong>Severity:</strong> ${payload.severity.toUpperCase()} |
          <strong>Source:</strong> ${escapeHtml(payload.source)} |
          <strong>Time:</strong> ${new Date(payload.timestamp).toISOString()}
        </div>
      </div>
      <div style="background: #0c0a09; color: #57534e; padding: 12px 24px; border-radius: 0 0 8px 8px; font-size: 11px;">
        Gravito AI — Alert Pipeline
      </div>
    </div>
  `;

  // Generic REST email API (SendGrid-compatible format)
  const emailPayload = {
    personalizations: recipients.map(to => ({ to: [{ email: to }] })),
    from: { email: fromEmail, name: 'Gravito Alerts' },
    subject: `[${payload.severity.toUpperCase()}] ${payload.title}`,
    content: [
      { type: 'text/plain', value: `${payload.title}\n\n${payload.content}\n\nSeverity: ${payload.severity}\nSource: ${payload.source}\nTime: ${new Date(payload.timestamp).toISOString()}` },
      { type: 'text/html', value: htmlBody },
    ],
  };

  const resp = await fetch(apiUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    },
    body: JSON.stringify(emailPayload),
    signal: AbortSignal.timeout(15_000),
  });

  if (!resp.ok) {
    throw new Error(`Email API returned HTTP ${resp.status}: ${await resp.text().catch(() => '')}`);
  }
}

/**
 * Send via SMS using a Twilio-compatible API.
 */
async function sendSMS(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
  const accountSid = config.settings.accountSid;
  const authToken = config.settings.authToken;
  const fromNumber = config.settings.fromNumber;
  const toNumbers = config.settings.toNumbers; // comma-separated

  if (!accountSid || !authToken || !fromNumber || !toNumbers) {
    throw new Error('SMS channel not fully configured (requires accountSid, authToken, fromNumber, toNumbers)');
  }

  const recipients = toNumbers.split(',').map(n => n.trim()).filter(Boolean);
  if (recipients.length === 0) throw new Error('No SMS recipients configured');

  // Truncate for SMS (160 char limit per segment)
  const smsBody = `[Gravito ${payload.severity.toUpperCase()}] ${payload.title}\n${payload.content}`.slice(0, 1500);

  const apiUrl = config.settings.apiUrl || `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
  const authHeader = 'Basic ' + Buffer.from(`${accountSid}:${authToken}`).toString('base64');

  // Send to each recipient
  const errors: string[] = [];
  for (const to of recipients) {
    try {
      const resp = await fetch(apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Authorization': authHeader,
        },
        body: new URLSearchParams({ To: to, From: fromNumber, Body: smsBody }).toString(),
        signal: AbortSignal.timeout(15_000),
      });

      if (!resp.ok) {
        errors.push(`${to}: HTTP ${resp.status}`);
      }
    } catch (err: any) {
      errors.push(`${to}: ${err?.message ?? 'unknown'}`);
    }
  }

  if (errors.length > 0) {
    throw new Error(`SMS delivery failed for: ${errors.join('; ')}`);
  }
}

/**
 * Send via generic webhook (HTTP POST with JSON body).
 */
async function sendWebhook(config: ChannelConfig, payload: NotificationPayload): Promise<void> {
  const url = config.settings.url;
  if (!url) throw new Error('Webhook URL not configured');

  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };

  // Optional auth header
  if (config.settings.authHeader) {
    headers['Authorization'] = config.settings.authHeader;
  }

  // Optional custom headers (JSON-encoded)
  if (config.settings.customHeaders) {
    try {
      const custom = JSON.parse(config.settings.customHeaders);
      Object.assign(headers, custom);
    } catch { /* ignore malformed headers */ }
  }

  const body = {
    event: 'gravito.alert',
    severity: payload.severity,
    title: payload.title,
    content: payload.content,
    source: payload.source,
    timestamp: payload.timestamp,
    metadata: payload.metadata ?? {},
  };

  const resp = await fetch(url, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
    signal: AbortSignal.timeout(10_000),
  });

  if (!resp.ok) {
    throw new Error(`Webhook returned HTTP ${resp.status}: ${await resp.text().catch(() => '')}`);
  }
}

/**
 * Send via in-app notification (Manus notification service).
 */
async function sendInApp(_config: ChannelConfig, payload: NotificationPayload): Promise<void> {
  const { notifyOwnerDirect } = await import('../_core/notification');
  const delivered = await notifyOwnerDirect({
    title: payload.title,
    content: payload.content,
  });
  if (!delivered) {
    throw new Error('In-app notification delivery failed');
  }
}

// ============================================================================
// SENDER REGISTRY
// ============================================================================

const SENDERS: Record<ChannelType, (config: ChannelConfig, payload: NotificationPayload) => Promise<void>> = {
  in_app: sendInApp,
  slack: sendSlack,
  email: sendEmail,
  sms: sendSMS,
  webhook: sendWebhook,
};

// ============================================================================
// HTML ESCAPE HELPER
// ============================================================================

function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// ============================================================================
// MULTI-CHANNEL NOTIFIER
// ============================================================================

export class MultiChannelNotifier {
  private channels: Map<string, ChannelConfig> = new Map();
  private stats: Map<string, {
    totalSent: number;
    totalFailed: number;
    totalRetried: number;
    sentThisHour: number;
    lastDelivery: number | null;
    lastError: string | null;
    latencies: number[];
  }> = new Map();
  private deliveryLog: DeliveryResult[] = [];
  private hourResetTimer: ReturnType<typeof setInterval> | null = null;

  constructor() {
    // Register default in-app channel
    this.registerChannel({
      id: 'in-app-default',
      type: 'in_app',
      name: 'In-App Notifications',
      enabled: true,
      minSeverity: 'info',
      maxPerHour: 50,
      retryCount: 1,
      retryDelayMs: 2000,
      settings: {},
    });

    // Auto-configure Slack from environment
    const slackUrl = process.env.SLACK_WEBHOOK_URL;
    if (slackUrl) {
      this.registerChannel({
        id: 'slack-default',
        type: 'slack',
        name: 'Slack Alerts',
        enabled: true,
        minSeverity: 'warning',
        maxPerHour: 30,
        retryCount: 2,
        retryDelayMs: 2000,
        settings: { webhookUrl: slackUrl },
      });
    }

    // Start hourly rate limit reset
    this.hourResetTimer = setInterval(() => {
      for (const [, stat] of this.stats) {
        stat.sentThisHour = 0;
      }
    }, 60 * 60 * 1000);
  }

  // ─── Channel Management ──────────────────────────────────────────────

  registerChannel(config: ChannelConfig): void {
    this.channels.set(config.id, { ...config });
    if (!this.stats.has(config.id)) {
      this.stats.set(config.id, {
        totalSent: 0,
        totalFailed: 0,
        totalRetried: 0,
        sentThisHour: 0,
        lastDelivery: null,
        lastError: null,
        latencies: [],
      });
    }
    generalLog.info({}, `[MultiChannel] Channel registered: ${config.name} (${config.type})`);
  }

  removeChannel(channelId: string): boolean {
    const removed = this.channels.delete(channelId);
    if (removed) {
      generalLog.info({}, `[MultiChannel] Channel removed: ${channelId}`);
    }
    return removed;
  }

  updateChannel(channelId: string, updates: Partial<Omit<ChannelConfig, 'id' | 'type'>>): ChannelConfig | null {
    const channel = this.channels.get(channelId);
    if (!channel) return null;

    const updated = { ...channel, ...updates };
    if (updates.settings) {
      updated.settings = { ...channel.settings, ...updates.settings };
    }
    this.channels.set(channelId, updated);
    return { ...updated };
  }

  getChannel(channelId: string): ChannelConfig | null {
    const ch = this.channels.get(channelId);
    return ch ? { ...ch } : null;
  }

  getChannels(): ChannelConfig[] {
    return Array.from(this.channels.values()).map(ch => ({
      ...ch,
      // Mask sensitive settings
      settings: Object.fromEntries(
        Object.entries(ch.settings).map(([k, v]) => {
          if (k.toLowerCase().includes('key') || k.toLowerCase().includes('token') || k.toLowerCase().includes('secret') || k.toLowerCase().includes('password')) {
            return [k, v ? `${v.slice(0, 6)}...` : ''];
          }
          return [k, v];
        })
      ),
    }));
  }

  // ─── Dispatch ────────────────────────────────────────────────────────

  /**
   * Dispatch a notification to all enabled channels matching severity.
   * Returns delivery results for each channel.
   */
  async dispatch(payload: NotificationPayload): Promise<DeliveryResult[]> {
    const results: DeliveryResult[] = [];

    for (const [channelId, config] of this.channels) {
      if (!config.enabled) continue;
      if (!meetsMinSeverity(payload.severity, config.minSeverity)) continue;

      const stat = this.stats.get(channelId)!;
      if (stat.sentThisHour >= config.maxPerHour) {
        generalLog.warn({}, `[MultiChannel] Rate limit reached for ${config.name}, skipping`);
        results.push({
          channelId,
          channelType: config.type,
          channelName: config.name,
          success: false,
          attempts: 0,
          latencyMs: 0,
          error: 'Rate limit exceeded',
          timestamp: Date.now(),
        });
        continue;
      }

      const result = await this.sendWithRetry(channelId, config, payload);
      results.push(result);
    }

    return results;
  }

  private async sendWithRetry(
    channelId: string,
    config: ChannelConfig,
    payload: NotificationPayload
  ): Promise<DeliveryResult> {
    const sender = SENDERS[config.type];
    if (!sender) {
      return {
        channelId,
        channelType: config.type,
        channelName: config.name,
        success: false,
        attempts: 0,
        latencyMs: 0,
        error: `Unknown channel type: ${config.type}`,
        timestamp: Date.now(),
      };
    }

    const stat = this.stats.get(channelId)!;
    let lastError: string | undefined;
    const startTime = Date.now();

    for (let attempt = 0; attempt <= config.retryCount; attempt++) {
      try {
        if (attempt > 0) {
          const delay = config.retryDelayMs * Math.pow(2, attempt - 1);
          await new Promise(r => setTimeout(r, delay));
          stat.totalRetried++;
        }

        await sender(config, payload);

        // Success
        const latencyMs = Date.now() - startTime;
        stat.totalSent++;
        stat.sentThisHour++;
        stat.lastDelivery = Date.now();
        stat.latencies.push(latencyMs);
        if (stat.latencies.length > 100) stat.latencies.splice(0, stat.latencies.length - 100);

        const result: DeliveryResult = {
          channelId,
          channelType: config.type,
          channelName: config.name,
          success: true,
          attempts: attempt + 1,
          latencyMs,
          timestamp: Date.now(),
        };

        this.deliveryLog.push(result);
        this.trimDeliveryLog();
        return result;
      } catch (err: any) {
        lastError = err?.message ?? 'Unknown error';
        generalLog.warn({}, `[MultiChannel] ${config.name} attempt ${attempt + 1} failed: ${lastError}`);
      }
    }

    // All attempts failed
    stat.totalFailed++;
    stat.lastError = lastError ?? 'Unknown error';

    const result: DeliveryResult = {
      channelId,
      channelType: config.type,
      channelName: config.name,
      success: false,
      attempts: config.retryCount + 1,
      latencyMs: Date.now() - startTime,
      error: lastError,
      timestamp: Date.now(),
    };

    this.deliveryLog.push(result);
    this.trimDeliveryLog();
    return result;
  }

  // ─── Stats & History ─────────────────────────────────────────────────

  getStats(): ChannelStats[] {
    return Array.from(this.channels.entries()).map(([channelId, config]) => {
      const stat = this.stats.get(channelId)!;
      const avgLatency = stat.latencies.length > 0
        ? stat.latencies.reduce((s, l) => s + l, 0) / stat.latencies.length
        : 0;

      return {
        channelId,
        channelType: config.type,
        channelName: config.name,
        enabled: config.enabled,
        totalSent: stat.totalSent,
        totalFailed: stat.totalFailed,
        totalRetried: stat.totalRetried,
        sentThisHour: stat.sentThisHour,
        lastDelivery: stat.lastDelivery,
        lastError: stat.lastError,
        avgLatencyMs: Math.round(avgLatency),
      };
    });
  }

  getDeliveryLog(limit = 50): DeliveryResult[] {
    return this.deliveryLog.slice(-limit);
  }

  getSummary(): {
    totalChannels: number;
    enabledChannels: number;
    channelTypes: ChannelType[];
    totalDelivered: number;
    totalFailed: number;
    overallSuccessRate: number;
  } {
    const stats = this.getStats();
    const totalDelivered = stats.reduce((s, c) => s + c.totalSent, 0);
    const totalFailed = stats.reduce((s, c) => s + c.totalFailed, 0);
    const total = totalDelivered + totalFailed;

    return {
      totalChannels: this.channels.size,
      enabledChannels: stats.filter(s => s.enabled).length,
      channelTypes: [...new Set(stats.map(s => s.channelType))],
      totalDelivered,
      totalFailed,
      overallSuccessRate: total > 0 ? totalDelivered / total : 1,
    };
  }

  // ─── Test Channel ────────────────────────────────────────────────────

  async testChannel(channelId: string): Promise<DeliveryResult> {
    const config = this.channels.get(channelId);
    if (!config) {
      return {
        channelId,
        channelType: 'webhook',
        channelName: 'Unknown',
        success: false,
        attempts: 0,
        latencyMs: 0,
        error: `Channel ${channelId} not found`,
        timestamp: Date.now(),
      };
    }

    const testPayload: NotificationPayload = {
      title: `Test Alert — ${config.name}`,
      content: `This is a test notification from Gravito Alert Pipeline.\nChannel: ${config.name} (${config.type})\nTime: ${new Date().toISOString()}`,
      severity: 'info',
      source: 'multi-channel-test',
      timestamp: Date.now(),
    };

    return this.sendWithRetry(channelId, config, testPayload);
  }

  // ─── Cleanup ─────────────────────────────────────────────────────────

  private trimDeliveryLog(): void {
    if (this.deliveryLog.length > 500) {
      this.deliveryLog.splice(0, this.deliveryLog.length - 500);
    }
  }

  reset(): void {
    this.channels.clear();
    this.stats.clear();
    this.deliveryLog = [];
    if (this.hourResetTimer) {
      clearInterval(this.hourResetTimer);
      this.hourResetTimer = null;
    }
  }

  destroy(): void {
    this.reset();
  }
}

// ============================================================================
// SINGLETON
// ============================================================================

let instance: MultiChannelNotifier | null = null;

export function getMultiChannelNotifier(): MultiChannelNotifier {
  if (!instance) instance = new MultiChannelNotifier();
  return instance;
}

export function resetMultiChannelNotifier(): void {
  if (instance) instance.destroy();
  instance = null;
}

