import { getDb } from '../db';
import { contentOverrides } from '../../drizzle/schema';
import { eq, desc, like } from 'drizzle-orm';
import { generalLog } from '../_core/logger';

export interface ContentOverride {
  id?: number;
  contentKey: string;
  contentValue: string;
  contentType: string;
  source: string;
  deploymentId: string | null;
  experimentId: string | null;
  isActive: boolean;
  createdAt: number;
  updatedAt: number;
}

const cache = new Map<string, { value: ContentOverride | null; expiresAt: number }>();
const TTL = 5 * 60 * 1000;

function getCached(key: string) {
  const e = cache.get(key);
  if (!e) return undefined;
  if (Date.now() > e.expiresAt) { cache.delete(key); return undefined; }
  return e.value;
}

function setCache(key: string, v: ContentOverride | null) {
  cache.set(key, { value: v, expiresAt: Date.now() + TTL });
}

export function clearContentCache() { cache.clear(); }

function mapRow(row: any): ContentOverride {
  return {
    id: row.id,
    contentKey: row.contentKey,
    contentValue: row.contentValue,
    contentType: row.contentType,
    source: row.source,
    deploymentId: row.deploymentId,
    experimentId: row.experimentId,
    isActive: row.isActive === 1,
    createdAt: row.createdAt,
    updatedAt: row.updatedAt,
  };
}

const MAX_CONTENT_VALUE_LENGTH = 1_000_000; // 1MB max content

function sanitizeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

export async function upsertContentOverride(o: {
  contentKey: string;
  contentValue: string;
  contentType?: string;
  source?: string;
  deploymentId?: string | null;
  experimentId?: string | null;
}): Promise<ContentOverride> {
  if (o.contentValue.length > MAX_CONTENT_VALUE_LENGTH) {
    throw new Error(`Content value exceeds max length of ${MAX_CONTENT_VALUE_LENGTH} bytes`);
  }
  // Sanitize HTML content to prevent stored XSS
  const safeValue = o.contentType === 'html' ? sanitizeHtml(o.contentValue) : o.contentValue;
  const db = await getDb();
  const now = Date.now();
  const existing = await db.select().from(contentOverrides).where(eq(contentOverrides.contentKey, o.contentKey)).limit(1);

  if (existing.length > 0) {
    await db.update(contentOverrides).set({
      contentValue: safeValue,
      contentType: o.contentType || existing[0].contentType,
      source: o.source || existing[0].source,
      deploymentId: o.deploymentId !== undefined ? o.deploymentId : existing[0].deploymentId,
      experimentId: o.experimentId !== undefined ? o.experimentId : existing[0].experimentId,
      updatedAt: now,
    }).where(eq(contentOverrides.contentKey, o.contentKey));
    const u = await db.select().from(contentOverrides).where(eq(contentOverrides.contentKey, o.contentKey)).limit(1);
    const r = mapRow(u[0]);
    setCache(o.contentKey, r);
    return r;
  }

  await db.insert(contentOverrides).values({
    contentKey: o.contentKey,
    contentValue: safeValue,
    contentType: o.contentType || 'text',
    source: o.source || 'manual',
    deploymentId: o.deploymentId || null,
    experimentId: o.experimentId || null,
    isActive: 1,
    createdAt: now,
    updatedAt: now,
  });
  const i = await db.select().from(contentOverrides).where(eq(contentOverrides.contentKey, o.contentKey)).limit(1);
  const r = mapRow(i[0]);
  setCache(o.contentKey, r);
  return r;
}

export async function getContentOverride(contentKey: string): Promise<ContentOverride | null> {
  const c = getCached(contentKey);
  if (c !== undefined) return c;
  try {
    const db = await getDb();
    const rows = await db.select().from(contentOverrides).where(eq(contentOverrides.contentKey, contentKey)).limit(1);
    if (!rows.length) { setCache(contentKey, null); return null; }
    const r = mapRow(rows[0]);
    setCache(contentKey, r);
    return r;
  } catch (err) { generalLog.warn({ err, contentKey }, '[CMS] Failed to get content override'); return null; }
}

export async function listContentOverrides(opts?: {
  prefix?: string;
  source?: string;
  activeOnly?: boolean;
  limit?: number;
}): Promise<ContentOverride[]> {
  try {
    const db = await getDb();
    let q = db.select().from(contentOverrides);
    if (opts?.prefix) {
      const sanitizedPrefix = opts.prefix.replace(/%/g, '\\%').replace(/_/g, '\\_');
      q = q.where(like(contentOverrides.contentKey, `${sanitizedPrefix}%`)) as any;
    }
    if (opts?.source) q = q.where(eq(contentOverrides.source, opts.source)) as any;
    const rows = await q.orderBy(desc(contentOverrides.updatedAt)).limit(opts?.limit || 100);
    return rows.map(mapRow).filter((r) => (opts?.activeOnly ? r.isActive : true));
  } catch (err) { generalLog.warn({ err }, '[CMS] Failed to list content overrides'); return []; }
}

export async function deleteContentOverride(contentKey: string): Promise<boolean> {
  try {
    const db = await getDb();
    await db.delete(contentOverrides).where(eq(contentOverrides.contentKey, contentKey));
    cache.delete(contentKey);
    return true;
  } catch (err) { generalLog.warn({ err, contentKey }, '[CMS] Failed to delete content override'); return false; }
}

