export interface MonitorConfig {
  enabled: boolean;
  intervalMs: number;
  maxPromotionsPerCycle: number;
  maxRollbacksPerCycle: number;
  enablePostDeployScans: boolean;
  dryRun: boolean;
}

export interface MonitorCycleResult {

const state = {
  isRunning: false,
  intervalHandle: null as ReturnType<typeof setInterval> | null,
  cycleCount: 0,
  lastCycleAt: null as number | null,
  recentCycles: [] as MonitorCycleResult[],
  totals: { totalPromoted: 0, totalRolledBack: 0, totalErrors: 0 },
  config: {
    enabled: true,
    intervalMs: 30 * 60 * 1000,
    maxPromotionsPerCycle: 3,
    maxRollbacksPerCycle: 5,
    enablePostDeployScans: true,
    dryRun: false,
  } as MonitorConfig,
};

export async function runMonitorCycle(): Promise<MonitorCycleResult> {

    for (const exp of experiments) {
      try {
        const r = await selfImproveRunner.monitorExperiment(exp.id);
        if (r.shouldPromote && pc < state.config.maxPromotionsPerCycle) {
          if (!state.config.dryRun) await selfImproveRunner.promoteExperiment(exp.id);
          promoted.push(exp.id);
          pc++;
          emitMonitorEvent({
            type: 'experiment_promoted',
            severity: 'success',
            source: 'monitor',
            title: `Experiment ${exp.id} promoted`,
            experimentId: exp.id,
            cycleId,
            details: state.config.dryRun ? 'Dry run — no actual promotion' : 'Promoted to production',
          });
          if (state.config.enablePostDeployScans) {
            try {
              await getClosedLoopScanner().scanDeployment(`monitor_promote_${exp.id}`, { source: 'autonomous-monitor' });
            } catch { /* non-critical */ }

