  id: string;
  name: string;
  description: string;
  /** Event types that trigger this rule */
  eventTypes: string[];
  /** Minimum severity to trigger ('info' | 'warning' | 'critical') */
  minSeverity: 'info' | 'warning' | 'critical';
  /** Whether this rule is active */
  enabled: boolean;
  /** Cooldown in ms between alerts of this type (prevents spam) */
  cooldownMs: number;
  /** Custom condition function (optional) */
  condition?: (event: AlertEvent) => boolean;
}

export interface AlertEvent {
  type: string;
  severity: 'info' | 'warning' | 'critical';
  title: string;
  details?: string;
  source: string;
  metrics?: Record<string, number | string>;
  timestamp: number;
}

