  id: string;
  ruleId: string;
  ruleName: string;
  eventType: string;
  severity: 'info' | 'warning' | 'critical';
  title: string;
  content: string;
  delivered: boolean;
  timestamp: number;
}

export interface AlertPipelineConfig {
  /** Global enable/disable */
  enabled: boolean;
  /** Maximum alerts per hour (circuit breaker) */
  maxAlertsPerHour: number;
  /** Global cooldown between any alerts (ms) */
  globalCooldownMs: number;
  /** Include metrics in alert content */
  includeMetrics: boolean;
  /** Alert channel preferences */
  channels: {
    inApp: boolean;
    /** Future: Slack webhook URL */
    slackWebhookUrl?: string;
    /** Future: Email recipients */
    emailRecipients?: string[];

