  // ─── Rollout Persistence ──────────────────────────────────────────────
  saveRolloutSnapshot: adminGuard.mutation(async () => {
    const ctrl = getRolloutController();
    const state = ctrl.getState();
    const config = ctrl.getConfig();
    const metrics = ctrl.getMetrics();
    // The snapshot stores the stage as its ordinal position, while the
    // controller tracks it as a named stage.
    const stageIndex = STAGE_ORDER.indexOf(state.currentStage);
    // Pass/fail totals are derived from the controller's retained health
    // history — it keeps no cumulative counters.
    const healthHistory = ctrl.getHealthHistory(200);
    const id = await saveRolloutState({
      status: state.status,
      currentStage: stageIndex >= 0 ? stageIndex : 0,
      percentage: state.rolloutPercentage,
      shadowMode: config.shadowMode,
      logAllRequests: config.logAllRequests,
      totalRequests: metrics.requestSummary.total,
      newVersionRequests: metrics.requestSummary.rolledOut,
      healthChecksPassed: healthHistory.filter(h => h.passed).length,
      healthChecksFailed: healthHistory.filter(h => !h.passed).length,
      consecutiveFailures: state.consecutiveHealthFailures,
      config,
      startedAt: state.startedAt,
      completedAt: state.completedAt,
    });
    return { success: true, rolloutId: id };
